parameters.message:
={
  "type": "AdaptiveCard",
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "version": "1.5",
  "body": [
    {
      "type": "TextBlock",
      "size": "Large",
      "weight": "Bolder",
      "text": "🚨 Ticket Escalado — Tier 2",
      "color": "Attention"
    },
    {
      "type": "FactSet",
      "facts": [
        { "title": "Ticket ID:", "value": "#{{ $('Service Bus Trigger').item.json.body.ticket_id }}" },
        { "title": "Tenant:", "value": "{{ $('Service Bus Trigger').item.json.body.tenant_id || 'default' }}" },
        { "title": "Persona:", "value": "{{ $('Service Bus Trigger').item.json.body.persona || 'cliente' }}" },
        { "title": "Categoria:", "value": "{{ $('Service Bus Trigger').item.json.body.category || 'geral' }}" },
        { "title": "Prioridade:", "value": "{{ $('Service Bus Trigger').item.json.body.priority || $('HTTP MCP — get_ticket').item.json.priority || 'medium' }}" },
        { "title": "Confiança IA:", "value": "{{ $('HTTP MCP — get_ticket').item.json.confidenceScore || 'n/a' }}" },
        { "title": "Escalado por:", "value": "{{ $('Service Bus Trigger').item.json.body.escalated_by || 'helpsphere-tier1-agent' }}" }
      ]
    },
    {
      "type": "TextBlock",
      "text": "**Resumo:** {{ $('Service Bus Trigger').item.json.body.summary || 'sem resumo' }}",
      "wrap": true,
      "spacing": "Medium"
    },
    {
      "type": "TextBlock",
      "text": "**Audit ID:** {{ $('PostgreSQL — Log Audit').item.json.id }}",
      "isSubtle": true,
      "size": "Small"
    }
  ],
  "actions": [
    {
      "type": "Action.OpenUrl",
      "title": "Abrir no HelpSphere",
      "url": "https://app-backend-helpsphere-prod.azurecontainerapps.io/tickets/{{ $('Service Bus Trigger').item.json.body.ticket_id }}",
      "style": "positive"
    },
    {
      "type": "Action.Submit",
      "title": "✓ Aceitar",
      "data": {
        "action": "accept",
        "ticket_id": "{{ $('Service Bus Trigger').item.json.body.ticket_id }}",
        "audit_id": "{{ $('PostgreSQL — Log Audit').item.json.id }}"
      }
    },
    {
      "type": "Action.Submit",
      "title": "✗ Rejeitar",
      "data": {
        "action": "reject",
        "ticket_id": "{{ $('Service Bus Trigger').item.json.body.ticket_id }}",
        "audit_id": "{{ $('PostgreSQL — Log Audit').item.json.id }}"
      }
    },
    {
      "type": "Action.Submit",
      "title": "↪ Reatribuir",
      "data": {
        "action": "reassign",
        "ticket_id": "{{ $('Service Bus Trigger').item.json.body.ticket_id }}",
        "audit_id": "{{ $('PostgreSQL — Log Audit').item.json.id }}"
      }
    }
  ]
}
